/* Base Mobile Styles (Default: Single Column Layout) */
.service-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
  padding: 1rem;
}

/* Tablet Viewport Enhancement (Width >= 640px) */
@media (min-width: 640px) {
  .service-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Desktop Viewport Enhancement (Width >= 1024px) */
@media (min-width: 1024px) {
  .service-grid {
    grid-template-columns: repeat(3, 1fr);
    max-width: 1200px;
    margin: 0 auto;
  }
}

